import {weatherDescription} from './weather-tools.js';
import {forecastSource,forecastSourceURL} from './weather-tools.js';
import {nextChangeHTML} from './next-change.js';
import {weatherSculpture} from './weather-sculpture.js';
import {forecastReceipt} from './forecast-receipt.js';
import {esc,miniWeather,weatherName,valueText,currentHour} from './weather-tools.js';
import {nextRain} from './atmosphere-core.js';
import {createDayPlan} from './day-plan.js';
import {CITIES} from './places.js';
const $=s=>document.querySelector(s);
// Keep the decorative 3D icon available without loading Three.js on Home.
const FEATURES={weatherArt3D:false};
export function createAtmosphere(ctx){
 const dayPlan=createDayPlan(ctx);
 setInterval(()=>{const slot=document.querySelector('#next-change-slot');if(!document.hidden&&slot&&!slot.querySelector('details[open]')&&!slot.contains(document.activeElement))slot.innerHTML=nextChangeHTML(ctx.get().weather)},60000);
 let following=[],followingUser='',followingBusy=false;let alert=null,alertKey='',alertAt=0,alertPending='',alertSequence=0,art=null,artKey='',artSequence=0,clashCities=[],clashAt=0,clashError='',clashBusy=false,first='milano',second='palermo',capture=null,captureStream=null,capturePhoto='',captureDraft='',captureKind='Osservazione',captureBusy=false,captureRevision=0,clock=0;
 const localKey=()=>ctx.get().place.latitude+','+ctx.get().place.longitude;
 function alertHTML(){if(alertKey!==localKey()||!alert)return '<div class="atmo-alert"><h2>Bollettini ufficiali</h2><p>Consulto la fonte per la località selezionata…</p><a href="https://rischi.protezionecivile.gov.it/it/meteo-idro/allertamento/" target="_blank" rel="noopener">Apri le fonti ufficiali ↗</a></div>';return `<section class="atmo-alert" data-mode="${esc(alert.mode)}" aria-label="Bollettino ufficiale"><p class="atmo-kicker">BOLLETTINO PER ${esc(ctx.get().place.name)}</p><h2>${esc(alert.title)}</h2><p>${esc(alert.detail)}</p>${alert.lastKnown?`<details><summary>Ultimo bollettino conservato · aggiornamento non verificato</summary><p>Valido per ${esc(alert.lastKnown.validDate)} · livello riportato: ${['nessuna allerta','giallo','arancione','rosso'][alert.lastKnown.level]}.</p><p>Ultima lettura riuscita: ${esc(new Date(alert.lastKnown.checkedAt).toLocaleString('it-IT'))}.</p><a href="${esc(alert.lastKnown.source)}" target="_blank" rel="noopener">Apri il bollettino conservato ↗</a></details>`:''}${alert.issued?`<p class="small">Ultimo controllo: ${esc(new Date(alert.checkedAt).toLocaleString('it-IT'))}. Zona individuata dalla posizione selezionata.</p>`:''}${alert.zones?.length?`<p>${alert.zones.map(z=>esc(z.name)).join(' · ')}</p>`:''}<small>${alert.issued?'Bollettino '+esc(alert.issued.replace(/^(\d{4})(\d{2})(\d{2})_(\d{2})(\d{2})_(?:today|tomorrow)$/, '$3/$2/$1 · emissione $4:$5'))+' · valido per '+esc(alert.validDate):'Stato delle allerte non verificabile in questa vista'}</small>${alert.zones?.some(z=>z.level>0)?`<details><summary>Fenomeni nel bollettino</summary>${alert.zones.map(z=>z.risks.map(r=>`<p><b>${esc(r.kind)}</b>: ${esc(r.text)}</p>`).join('')).join('')}</details>`:''}${alert.level>0&&['CAUTION','EMERGENCY'].includes(alert.mode)?'<p>Le scuole non chiudono automaticamente con l’allerta: decide il sindaco.</p><a class="button" href="#scuole">Domani le scuole sono chiuse qui?</a>':''}<div class="atmo-alert-links"><a href="${esc(alert.source)}" target="_blank" rel="noopener">Fonte: Protezione Civile ↗</a><a href="https://rischi.protezionecivile.gov.it/it/meteo-idro/" target="_blank" rel="noopener">Indicazioni ufficiali ↗</a>${alert.mode==='EMERGENCY'||alert.mode==='CAUTION'?'<a href="#stanza">Stanza meteo →</a>':''}<button data-atmo-alert-retry>Aggiorna</button></div></section>`}
 async function loadAlert(force=false){const key=localKey();if(alertPending===key||(!force&&alertKey===key&&Date.now()-alertAt<300000))return;alertPending=key;const token=++alertSequence;try{const p=ctx.get().place,data=await ctx.api('atmosphere/safety?'+new URLSearchParams({lat:p.latitude,lon:p.longitude}));if(token!==alertSequence)return;alert=data;alertKey=key;alertAt=Date.now()}catch{if(token!==alertSequence)return;alert={mode:'UNKNOWN',title:'Bollettino non disponibile',detail:'La fonte non ha risposto. Controlla il bollettino ufficiale della zona.',source:'https://rischi.protezionecivile.gov.it/it/meteo-idro/allertamento/'};alertKey=key;alertAt=Date.now()-240000}finally{if(token===alertSequence){alertPending='';if(key===localKey())document.querySelectorAll('[data-atmo-alert]').forEach(el=>el.innerHTML=alertHTML());bindAlert()}}}
 function followingHTML(){const c=CITIES.find(c=>c.name===ctx.get().place.name);return '<div class="atmo-following">'+(c?'<button data-atmo-follow="'+c.id+'" aria-pressed="'+following.some(x=>x.id===c.id)+'">'+(following.some(x=>x.id===c.id)?'✓ Città seguita':'+ Segui '+esc(c.name))+'</button>':'')+following.map(c=>'<button data-atmo-follow-open="'+esc(c.id)+'">'+esc(c.name)+'</button>').join('')+'</div>'}
 async function loadFollowing(){const id=ctx.get().me?.id||'';if(followingBusy||id===followingUser)return;followingUser=id;following=[];if(!id){following=[];paintFollowing();return}followingBusy=true;try{const result=await ctx.api('atmosphere/following');if((ctx.get().me?.id||'')===id)following=result.cities}catch{followingUser='';}finally{followingBusy=false;if((ctx.get().me?.id||'')!==id){followingUser='';following=[];loadFollowing()}paintFollowing()}}
 function paintFollowing(){const el=$('#atmo-following');if(el)el.innerHTML=followingHTML();bindFollowing()}
 function bindFollowing(){document.querySelectorAll('[data-atmo-follow]').forEach(b=>b.onclick=async()=>{if(!ctx.get().me)return ctx.login();b.disabled=true;try{await ctx.api('atmosphere/follow-city',{city:b.dataset.atmoFollow,active:!following.some(c=>c.id===b.dataset.atmoFollow)});followingUser='';await loadFollowing();ctx.toast('Città seguite aggiornate nel tuo account.')}catch(e){ctx.toast(e.message)}finally{b.disabled=false}});document.querySelectorAll('[data-atmo-follow-open]').forEach(b=>b.onclick=()=>{const c=CITIES.find(c=>c.id===b.dataset.atmoFollowOpen);if(c)ctx.choose(c)})}
 function weatherBlock(){const {weather:w,weatherError,place}=ctx.get(),c=w?.current;if(!c&&!weatherError)return `<section class="atmo-weather" data-ui-loading="true" aria-busy="true"><div><h2>${esc(place.name)}</h2><div class="atmo-temperature" aria-hidden="true">—°</div><p role="status">Caricamento delle previsioni…</p><div class="atmo-weather-meta" aria-hidden="true"><span>Percepiti —°</span><span>Vento — km/h</span><span>Min —° / Max —°</span></div></div><div class="weather-art" aria-hidden="true"></div></section>`;if(!c)return `<section class="atmo-weather"><div><h2>${esc(place.name)}</h2><p role="status">${weatherError?'Il meteo non risponde. La città è conservata.':'Caricamento delle previsioni…'}</p><button data-refresh-weather>Riprova</button><a href="#mappa">Scegli una città</a></div></section>`;return `${weatherSculpture(c)}<section class="atmo-weather"><div><h2>${esc(place.name)}</h2><div class="atmo-temperature">${valueText(c.temperature_2m,'°')}</div><p>${esc(weatherDescription(c))}</p><div class="atmo-weather-meta"><span>Percepiti ${valueText(c.apparent_temperature,'°')}</span><span>Vento ${valueText(c.wind_speed_10m,' km/h')}</span><span>Min ${valueText(w.daily?.temperature_2m_min?.[0],'°')} / Max ${valueText(w.daily?.temperature_2m_max?.[0],'°')}</span></div></div><div class="weather-art" id="atmo-weather-art" aria-label="${esc(weatherDescription(c))}">${miniWeather(c.weather_code,c.is_day!==0)}</div></section>${forecastReceipt(w)}`}
 function rainBlock(){const r=nextRain(ctx.get().weather);return `<div class="atmo-rain"><span aria-hidden="true">☂</span><div><h2>${esc(r.title)}</h2><p>${esc(r.detail)}</p></div><a href="#mappa-eventi">Apri mappa e radar ↗</a></div>`}
 function hours(){const w=ctx.get().weather,i=currentHour(w);if(i<0)return '';return `<div class="forecast-hours" tabindex="0" role="region" aria-label="Previsioni orarie scorrevoli">${w.hourly.time.slice(i,i+5).map((t,n)=>`<article><time>${t.slice(11,16)}</time>${miniWeather(w.hourly.weather_code?.[i+n],w.hourly.is_day?.[i+n]!==0)}<b>${valueText(w.hourly.temperature_2m?.[i+n],'°')}</b><span>${valueText(w.hourly.precipitation_probability?.[i+n],'%')}</span></article>`).join('')}</div>`}
 function home(socialSlot=""){return `<section class="atmo-home cielo-home"><div class="atmo-heading"><div><h1>Il cielo <em>adesso.</em></h1></div><button data-search-place>⌖ Cambia città</button></div><div class="home-overview"><div class="cielo-weather-stage home-weather-scene"><div id="atmo-weather">${weatherBlock()}</div></div><div id="next-change-slot">${nextChangeHTML(ctx.get().weather)}</div></div><div class="calendar-strip calendar-scene"><div class="calendar-copy"><div class="calendar-meta"><span class="calendar-badge" data-calendar-label>Il tuo cielo</span><time data-calendar-date></time></div><p data-calendar-caption></p></div><div class="calendar-art" data-calendar-art aria-hidden="true"></div></div><div class="atmo-actions" aria-label="Cosa puoi fare"><a href="#tendenze"><strong>Previsioni</strong><small>Temperature e pioggia, ora per ora</small></a><a href="#mappa-eventi"><strong>Mappa e radar</strong><small>Esplora il meteo e le segnalazioni</small></a><a href="#segnala"><strong>Segnala</strong><small>Racconta cosa vedi nella tua zona</small></a></div><div id="atmo-following">${followingHTML()}</div><div id="atmo-rain">${rainBlock()}</div><div data-atmo-alert>${alertHTML()}</div><a class="hail-entry" href="#grandine-mappa"><span><strong>Grandine: guarda le segnalazioni</strong><small>Osservazioni della community, non allerte ufficiali.</small></span><span aria-hidden="true">↗</span></a><details class="atmo-more" ${new URLSearchParams(globalThis.location?.search||'').get('view')==='giornata'?'open':''}><summary>Organizza la tua giornata</summary>${dayPlan.html()}</details><details class="atmo-more"><summary>Community e altre funzioni</summary><section class="atmo-panel"><h2>Il cielo visto dalle persone.</h2><p>Leggi le osservazioni della zona o condividi la tua.</p><div class="actions"><button data-atmo-community>Apri la community locale</button><a href="#studio">Crea una storia →</a><a href="#testimonianza">Scatta una testimonianza →</a></div>${socialSlot}<a class="atmo-orbit-link" href="#clash"><span><b>Confronta due città</b><small>Meteo Clash: il meteo a confronto</small></span><span>↗</span></a><div class="actions"><a href="#fitcheck">Come vestirsi →</a><a href="#sfide">Sfide delle città →</a><button data-atmo-narrate>Ascolta il bollettino con Lente</button></div></section><div data-home-extras></div></details><details class="atmo-tour"><summary>Come funziona MeteoSocial?</summary><ol><li>Scegli una città per leggere le previsioni.</li><li>Apri la mappa per esplorare dati e segnalazioni.</li><li>Premi Segnala per raccontare il tempo da te.</li></ol><a href="#guida">Guida completa e fonti →</a></details><p id="atmo-source" class="atmo-footer">${sourceLine()}</p></section>`}
 function sourceLine(){const w=ctx.get().weather;return `Previsioni: <a href="${forecastSourceURL(w)}" target="_blank" rel="noopener">${forecastSource(w)}</a>${w?' · '+esc(w.current.time.replace('T',' '))+' · '+esc(w.timezone):' · in attesa del dato'}. Le testimonianze della community non sono allerte.`}
 function clashCard(id,pos){const c=clashCities.find(c=>c.id===id),w=c?.current;return `<article class="atmo-clash-city"><label for="clash-${pos}">${pos==='first'?'Prima città':'Seconda città'}</label><select id="clash-${pos}">${CITIES.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div>${w?miniWeather(w.weather_code,w.is_day!==0):''}<h2>${valueText(w?.temperature_2m,'°')}</h2><p>${w?weatherName(w.weather_code):clashError||'Caricamento…'}</p><small>${w?'Open-Meteo · '+esc(w.time.replace('T',' '))+' UTC':'Nessun valore inventato in attesa della fonte'}</small></div><button data-clash-community="${esc(id)}">Guarda la community →</button></article>`}
 function clashSummary(){const a=clashCities.find(c=>c.id===first),b=clashCities.find(c=>c.id===second);return a?.current&&b?.current?first===second?'Scegli due città diverse.':Math.abs(a.current.temperature_2m-b.current.temperature_2m).toFixed(1)+'° di differenza. Due modi di vivere il cielo.':'Confronto dei dati del modello per lo stesso aggiornamento.'}
 function clash(){return `<section class="atmo-clash"><div class="atmo-heading"><div><p>STESSO PIANETA · DUE PROSPETTIVE</p><h1>Meteo Clash</h1></div><a href="#home">← Oggi</a></div><div id="clash-grid" class="atmo-clash-grid">${clashCard(first,'first')}${clashCard(second,'second')}</div><div class="atmo-clash-summary" id="clash-summary">${clashSummary()}</div><div class="actions"><button class="button" data-clash-export>Scarica la card verticale</button><button data-clash-share>Condividi il confronto</button><button data-clash-refresh>Aggiorna dati</button></div><p class="atmo-footer">Dati del modello, non riprese live. La card conserva città, fonti e orari. Per vedere foto e video apri la community.</p><div data-atmo-alert>${alertHTML()}</div></section>`}
 async function loadClash(force=false){if(clashBusy||clashCities.length&&Date.now()-clashAt<600000&&!force)return;clashBusy=true;clashError='';try{clashCities=(await ctx.api('atlas/cities')).cities;clashAt=Date.now()}catch{clashError='Confronto non disponibile. Premi Aggiorna dati.'}finally{clashBusy=false;paintClash()}}
 function paintClash(){if(!$('#clash-grid'))return;$('#clash-grid').innerHTML=clashCard(first,'first')+clashCard(second,'second');$('#clash-summary').textContent=clashSummary();bindClash()}
 function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
 async function exportClash(share=false){if(Date.now()-clashAt>=600000){await loadClash(true);if(Date.now()-clashAt>=600000)return ctx.toast('Aggiorna i dati prima di esportare il confronto.');}const a=clashCities.find(c=>c.id===first),b=clashCities.find(c=>c.id===second);if(!a?.current||!b?.current||first===second)return ctx.toast('Scegli due città diverse con dati disponibili.');const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const x=canvas.getContext('2d');x.fillStyle='#071321';x.fillRect(0,0,1080,1920);x.fillStyle='#8de9ef';x.font='700 34px system-ui';x.fillText('METEOSOCIAL / METEO CLASH',72,170);[a,b].forEach((c,i)=>{const y=270+i*650;x.fillStyle=i?'#29293f':'#17364c';x.fillRect(48,y,984,600);x.fillStyle='#fff';x.font='700 54px system-ui';x.fillText(c.name,84,y+95,900);x.font='800 172px system-ui';x.fillText(Math.round(c.current.temperature_2m)+'°',84,y+300);x.font='36px system-ui';x.fillText(weatherName(c.current.weather_code),84,y+390);x.font='28px system-ui';x.fillStyle='#c1d7e3';x.fillText('Open-Meteo · '+c.current.time.replace('T',' ')+' UTC',84,y+480,900)});x.fillStyle='#7ce6ed';x.font='700 44px system-ui';x.fillText(Math.abs(a.current.temperature_2m-b.current.temperature_2m).toFixed(1)+'° DI DIFFERENZA',72,1670);x.fillStyle='#c3d5e1';x.font='26px system-ui';x.fillText('Previsione da modello · non un’allerta',72,1740);x.fillText(location.origin,72,1800,935);canvas.toBlob(async blob=>{if(!blob)return ctx.toast('Card non disponibile. Riprova.');const file=new File([blob],'meteosocial-clash.png',{type:'image/png'});if(share&&navigator.canShare?.({files:[file]}))try{await navigator.share({files:[file],title:'Meteo Clash'});return}catch(e){if(e.name==='AbortError')return}download(blob,'meteosocial-clash.png')},'image/png')}
 function bindClash(){for(const pos of ['first','second'])$('#clash-'+pos)?.addEventListener('change',e=>{if(pos==='first')first=e.target.value;else second=e.target.value;paintClash()});document.querySelectorAll('[data-clash-community]').forEach(b=>b.onclick=()=>{const p=CITIES.find(c=>c.id===b.dataset.clashCommunity);if(p)ctx.community(p.name,true)})}
 function capturePage(){return `<section class="atmo-home"><div class="atmo-heading"><div><p>TESTIMONIANZA ADESSO</p><h1>Il cielo, come lo vedi tu.</h1></div><a href="#studio">Storia creativa →</a></div><div data-atmo-alert>${alertHTML()}</div><section class="atmo-panel"><div class="atmo-heading"><div><h2>${esc(capture?.city||ctx.get().place.name)}</h2><p>Foto dalla fotocamera · senza caricamento dalla galleria</p></div><span id="capture-clock" class="atmo-capture-clock"></span></div><video id="capture-video" class="atmo-capture-preview" muted playsinline hidden></video><img id="capture-photo" class="atmo-capture-preview" alt="Foto scattata in questa sessione" ${capturePhoto?'src="'+capturePhoto+'"':'hidden'}><div class="atmo-capture-actions"><button class="button" data-capture-start>Apri fotocamera</button><button data-capture-shot hidden>Scatta adesso</button><button data-capture-stop hidden>Ferma fotocamera</button><button data-capture-download ${capturePhoto?'':'hidden'}>Scarica originale</button></div><p id="capture-status" class="atmo-capture-status" role="status">Apri una sessione di tre minuti. Riprendi soltanto da un posto protetto.</p><label class="field">Cosa osservi?<select id="capture-kind" class="atmo-report-kind">${['Osservazione','Pioggia','Vento','Grandine','Neve','Cielo sereno','Allagamento'].map(k=>`<option ${captureKind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">Il tuo racconto<textarea id="capture-text" maxlength="700" placeholder="Descrivi ciò che vedi, senza indirizzi privati.">${esc(captureDraft)}</textarea></label><label class="studio-check"><input id="capture-confirm" type="checkbox"> Posso condividere la foto e ho controllato persone e dati privati.</label><button class="button" data-capture-publish ${capturePhoto?'':'disabled'}>Pubblica testimonianza</button><p class="atmo-footer">La sessione registra un orario server e l’impronta del file. Non certifica luogo, verità della scena o dimensioni della grandine. La segnalazione resta visibile per due ore. Nessun invio automatico e nessun microfono.</p></section></section>`}
 function captureStatus(s){if($('#capture-status'))$('#capture-status').textContent=s}
 function stopCamera(){captureStream?.getTracks().forEach(t=>t.stop());captureStream=null;const v=$('#capture-video');if(v){v.pause();v.srcObject=null;v.hidden=true}if($('[data-capture-shot]'))$('[data-capture-shot]').hidden=true;if($('[data-capture-stop]'))$('[data-capture-stop]').hidden=true;clearInterval(clock);clock=0}
 function paintClock(){const left=capture?Math.max(0,Math.ceil((capture.expires-(Date.now()+capture.offset))/1000)):0;const el=$('#capture-clock');if(el)el.textContent=capture?Math.floor(left/60)+':'+String(left%60).padStart(2,'0'):'';if(capture&&!left){stopCamera();captureStatus('Sessione scaduta. Scarica la foto o avvia una nuova ripresa.');if($('[data-capture-publish]'))$('[data-capture-publish]').disabled=true}}
 async function startCapture(){if(captureBusy)return;if(!ctx.get().me)return ctx.login();if(!navigator.mediaDevices?.getUserMedia)return captureStatus('Fotocamera non disponibile in questo browser. Puoi creare una storia dallo Studio.');captureBusy=true;const city=ctx.get().place.name,placeKey=localKey(),token=++captureRevision;stopCamera();try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280},height:{ideal:720}},audio:false});if(token!==captureRevision||placeKey!==localKey()){stream.getTracks().forEach(t=>t.stop());return}captureStream=stream;const ticket=await ctx.api('atmosphere/ticket',{city});if(token!==captureRevision||placeKey!==localKey()||ctx.get().route!=='testimonianza'){stopCamera();return}capture={...ticket,offset:ticket.serverNow-Date.now()};capturePhoto='';$('[data-capture-download]').hidden=true;const video=$('#capture-video');video.srcObject=stream;video.hidden=false;$('#capture-photo').hidden=true;await video.play();if(token!==captureRevision){stopCamera();return}$('[data-capture-shot]').hidden=false;$('[data-capture-stop]').hidden=false;$('[data-capture-publish]').disabled=true;$('#capture-confirm').checked=false;captureStatus('Fotocamera attiva. Scatta quando sei pronto. La foto non viene inviata finché premi Pubblica.');paintClock();clock=setInterval(paintClock,1000)}catch(e){stopCamera();captureStatus(e.name==='NotAllowedError'?'Accesso alla fotocamera negato. Puoi modificare il permesso nel browser.':e.message||'Fotocamera non disponibile.')}finally{captureBusy=false}}
 function shoot(){const v=$('#capture-video');if(!v?.videoWidth||!capture||Date.now()+capture.offset>=capture.expires)return;const c=document.createElement('canvas'),scale=Math.min(1,1280/v.videoWidth);c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);c.getContext('2d').drawImage(v,0,0,c.width,c.height);capturePhoto=c.toDataURL('image/jpeg',.82);stopCamera();$('#capture-photo').src=capturePhoto;$('#capture-photo').hidden=false;$('[data-capture-download]').hidden=false;$('[data-capture-publish]').disabled=false;captureStatus('Foto pronta. Controlla il testo e conferma prima di pubblicare.');paintClock();clock=setInterval(paintClock,1000)}
 async function publishCapture(){if(captureBusy||!capturePhoto||!capture)return;if(!$('#capture-confirm').checked)return captureStatus('Conferma il diritto di condividere questa foto.');captureBusy=true;$('[data-capture-publish]').disabled=true;try{const result=await ctx.api('atmosphere/report',{id:capture.id,photo:capturePhoto,text:captureDraft,kind:captureKind,confirm:true});capturePhoto='';capture=null;captureDraft='';stopCamera();ctx.invalidate();location.hash='post:'+result.id;ctx.toast('Testimonianza pubblicata. La provenienza non certifica l’evento.')}catch(e){captureStatus(e.message)}finally{captureBusy=false;if($('[data-capture-publish]'))$('[data-capture-publish]').disabled=false}}
 function bindAlert(){document.querySelectorAll('[data-atmo-alert-retry]').forEach(b=>b.onclick=()=>loadAlert(true))}
 function bind(){const r=ctx.get().route;document.body.classList.toggle('atmospheric-home',['home','clash','testimonianza','grandine'].includes(r));if($('[data-atmo-alert]'))loadAlert();bindAlert();document.querySelectorAll('[data-atmo-community]').forEach(b=>b.onclick=()=>ctx.community(ctx.get().place.name));$('[data-atmo-narrate]')?.addEventListener('click',()=>ctx.askAI('Racconta il meteo della località in massimo 40 parole con la personalità scelta. Mantieni una parte utile e distingui le previsioni dalle allerte.'));
 if(r==='home'){dayPlan.bind();mountArt();loadFollowing();bindFollowing()}if(r==='clash'){bindClash();loadClash();$('[data-clash-export]').onclick=()=>exportClash();$('[data-clash-share]').onclick=()=>exportClash(true);$('[data-clash-refresh]').onclick=()=>loadClash(true)}
 if(r==='testimonianza'){$('[data-capture-start]').onclick=startCapture;$('[data-capture-shot]').onclick=shoot;$('[data-capture-stop]').onclick=()=>{captureRevision++;stopCamera();captureStatus('Fotocamera spenta.')} ;$('[data-capture-publish]').onclick=publishCapture;$('[data-capture-download]').onclick=()=>{if(!capturePhoto)return;const a=document.createElement('a');a.href=capturePhoto;a.download='meteosocial-originale.jpg';a.click()};$('#capture-text').oninput=e=>captureDraft=e.target.value;$('#capture-kind').onchange=e=>captureKind=e.target.value;paintClock();if(capture)clock=setInterval(paintClock,1000)}}
 async function mountArt(){}
 function refresh(){dayPlan.refresh();if(ctx.get().route==='home'){$('#atmo-weather').innerHTML=weatherBlock();$('#atmo-rain').innerHTML=rainBlock();if($('#next-change-slot'))$('#next-change-slot').innerHTML=nextChangeHTML(ctx.get().weather);$('#atmo-source').innerHTML=sourceLine();mountArt()}if($('[data-atmo-alert]')){if(alertKey!==localKey())document.querySelectorAll('[data-atmo-alert]').forEach(el=>el.innerHTML=alertHTML());loadAlert()}}
 setInterval(()=>{if(!document.hidden&&$('[data-atmo-alert]'))loadAlert()},300000);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){captureRevision++;stopCamera();captureStatus('Fotocamera fermata: app in background.')}else{paintClock();if($('[data-atmo-alert]'))loadAlert()}});
 return {dayPlan,home,clash,capturePage,alertHTML,bind,refresh,dispose(next){artSequence++;art?.();art=null;if(next!=='testimonianza'){captureRevision++;stopCamera()}},safety:()=>alertKey===localKey()?alert:null};
}
